"use client";

import { useEffect, useRef, useState } from "react";
import { AnimatePresence, motion } from "framer-motion";

interface AccordionItem {
  id: number;
  title: string;
  description: string;
  src?: string;
}

interface FeatureAccordionProps {
  data: AccordionItem[];
  isParentActive: boolean;
  onAccordionChange: (activeIndex: number) => void;
}

export default function FeatureAccordion({
  data,
  isParentActive,
  onAccordionChange,
}: FeatureAccordionProps) {
  const accordionData = data;
  const [accordion, setAccordion] = useState(0);
  const [isMobile, setIsMobile] = useState(false);

  const wasActiveRef = useRef(false);

  useEffect(() => {
    const handleResize = () => {
      setIsMobile(window.innerWidth < 1024);
    };

    handleResize();
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  // When this card becomes active (scrolls into view), always restart the
  // accordion from the first item — never resume from wherever it was.
  useEffect(() => {
    if (isParentActive && !wasActiveRef.current) {
      setAccordion(0);
    }
    wasActiveRef.current = isParentActive;
  }, [isParentActive]);

  useEffect(() => {
    if (isParentActive) {
      onAccordionChange(accordion);
    }
  }, [accordion, isParentActive, onAccordionChange]);

  // Auto-advance only while this card is the active/visible one.
  // Off-screen cards no longer tick in the background.
  useEffect(() => {
    if (isMobile || !isParentActive) return;

    const interval = setInterval(() => {
      setAccordion((prev) => (prev + 1) % accordionData.length);
    }, 6000);

    return () => clearInterval(interval);
  }, [accordionData.length, isMobile, isParentActive]);

  return (
    <div className="flex w-full flex-col gap-2.5">
      {accordionData.map((item, index) => {
        const isOpen = isMobile ? true : accordion === index;
        const isCurrentlySelected = accordion === index;

        return (
          <div
            key={item.id}
            onClick={() => setAccordion(index)}
            className={`w-full cursor-pointer rounded-[10px] p-3.5 transition-all duration-200 sm:p-4 ${
              isCurrentlySelected ? "bg-white" : ""
            }`}
          >
            <div className="relative flex gap-3">
              <div
                className={`mt-1 transition-colors duration-300 ${
                  isCurrentlySelected ? "opacity-100" : "opacity-20"
                }`}
              >
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  xmlnsXlink="http://www.w3.org/1999/xlink"
                  width="20"
                  height="24"
                  fill="none"
                  viewBox="0 0 20 24"
                >
                  <path
                    fill="url(#pattern0_3594_2405)"
                    d="M0 2h20v20H0z"
                  ></path>
                  <defs>
                    <pattern
                      id="pattern0_3594_2405"
                      width="1"
                      height="1"
                      patternContentUnits="objectBoundingBox"
                    >
                      <use
                        xlinkHref="#image0_3594_2405"
                        transform="scale(.0013)"
                      ></use>
                    </pattern>
                    <image
                      xlinkHref="data:image/png;base64,"
                      id="image0_3594_2405"
                      width="768"
                      height="768"
                      preserveAspectRatio="none"
                    ></image>
                  </defs>
                </svg>
              </div>
              <div className="flex-1">
                <p
                  className={`text-[14px] leading-tight font-medium ${
                    isCurrentlySelected ? "text-[#0F172A]" : "text-[#64748B]"
                  } `}
                >
                  {item.title}
                </p>

                <AnimatePresence initial={false}>
                  {isOpen && (
                    <motion.div
                      initial={
                        isMobile
                          ? false
                          : {
                              height: 0,
                              opacity: 0,
                              filter: "blur(8px)",
                            }
                      }
                      animate={{
                        height: "auto",
                        opacity: 1,
                        filter: "blur(0px)",
                      }}
                      exit={
                        isMobile
                          ? undefined
                          : {
                              height: 0,
                              opacity: 0,
                              filter: "blur(8px)",
                            }
                      }
                      transition={{
                        duration: 0.3,
                        ease: "easeOut",
                      }}
                      className="overflow-hidden"
                    >
                      <p className="mt-1.5 text-[12px] leading-relaxed font-normal text-[#262E41] sm:text-[14px]">
                        {item.description}
                      </p>
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}
